// ✅ NEW: The action is a server endpoint. Native POST works without
// JS; use:enhance upgrades it to a fetch-based submit with no reload.
export const actions = {
  default: async ({ request }) => {
    const fd = await request.formData();
    const email = String(fd.get('email') ?? '');

    if (!email.includes('@')) {
      return { error: 'Invalid email' }; // ✅ NEW: returned to the form
    }
    return { ok: true }; // ✅ NEW: success result
  },
};

